"""Request independent physical recoil guides, never reuse attack keyframes as hurt motion."""
import json,argparse
from street_comfy import ROOT,qwen,submit
props={1:'golden yellow bull, short swept blond hair, black horns, purple muzzle, NAVY suit, white shirt and RED tie, empty hands',5:'round WHITE bull with exact BLACK patches, short black hair, black horns and pink muzzle/hooves, empty hands',13:'yellow safety marshal bull, white hardhat/horn cutouts, orange reflective vest over navy workwear, pale gloves and brown boots, RED radio permanently in anatomical RIGHT hand on viewer LEFT'}
parser=argparse.ArgumentParser();parser.add_argument('ids',nargs='*',type=int,default=[1,5,13]);parser.add_argument('--revision',type=int,default=1);args=parser.parse_args()
for hid in args.ids:
 name=f'hero{hid:03}-hurt-v{args.revision}';folder=ROOT/'art-migration/generation'/name
 if folder.exists():continue
 prompt=f'''Create ONE full-body physical HURT/RECOIL guide pose of EXACT reference character: {props[hid]}. Same species, face, clothing colors, proportions, horns, all persistent props and hand assignment. Keep mostly front-facing with slight right-facing three-quarter orientation. A modest startled flinch: torso leans BACK slightly, shoulders recoil, knees bend, chin tucked, hands protect chest; no attack or outgoing punch. Both feet stay on the same ground line, no jump or dramatic twist. {('RIGHT hand retains existing red radio at hip and EMPTY LEFT palm guards chest.' if hid==13 else 'Both hands are EMPTY and NO objects, radios, bags, tools or belt attachments may be added anywhere.')} Preserve all items, no doubled arms. Full head/horns/hands/feet inside large safe margins. Tactile2.5D semi-realistic semi-cartoon absurd neighborhood game illustration, same soft light and material palette. Plain white background, no environment, no target, no wounds, no blood, no VFX, no flash, no shock lines, no text.'''
 g=qwen(prompt,ROOT/f'local_game/assets/street/characters/{hid:03}/portrait.png',768,28,202610294300+hid+args.revision*100);g['11']={'class_type':'SplitImageWithAlpha','inputs':{'image':['6',0]}};g['9']={'class_type':'easy imageRemBg','inputs':{'images':['11',0],'rem_mode':'RMBG-1.4','image_output':'Hide','save_prefix':'street-reskin/matte','add_background':'none','torchscript_jit':False,'refine_foreground':False}};g['10']={'class_type':'SaveImage','inputs':{'images':['9',0],'filename_prefix':f'street-reskin/hero{hid:03}_hurt_alpha'}};folder=submit(g,name,front=False);(folder/'design.json').write_text(json.dumps({'heroId':hid,'action':'hurt','prompt':prompt,'reference':f'local_game/assets/street/characters/{hid:03}/portrait.png','manualReview':'pending','runtimeIntegrated':False},indent=2)+'\n','utf8')
